function relationshipValue(r){const v=r?.value||{};if(v.kind==="EXACT"&&v.measurementType==="percentage")return`Exactly ${v.exact}%`;if(v.kind==="EXACT"&&v.measurementType==="count_of_total")return`${v.numerator} of ${v.denominator}`;if(v.kind==="EXACT")return`${v.exact}${v.unit?` ${v.unit}`:""}`;if(v.kind==="RANGE")return`${v.lower!=null?(v.lowerInclusive?"≥":">")+v.lower:""}${v.lower!=null&&v.upper!=null?" and ":""}${v.upper!=null?(v.upperInclusive?"≤":"<")+v.upper:""}${v.measurementType==="percentage"?"%":""}`;if(v.kind==="QUALITATIVE")return v.qualitative||"Qualitative source statement";return`Unknown value (${v.measurementType||"none"})`;}function partyName(p){return p?.name||p?.description||"Source party not named";}function relationshipCard(r,locators=[]){if(!r)return"";return`<section class="artifact"><span class="badge live">SOURCE ASSERTION — TYPED R4</span><div class="row"><div class="field"><b>${esc(partyName(r.subject))}</b><br><span class="meta">${esc(r.subject?.partyType)}</span></div><div class="field"><b>${esc(String(r.relationshipType||"").replace(/_/g," "))}</b><br><span class="meta">subject → relationship → object</span></div><div class="field"><b>${esc(partyName(r.object))}</b><br><span class="meta">${esc(r.object?.partyType)}</span></div></div><p><b>Value:</b> ${esc(relationshipValue(r))}<br><b>Temporal state:</b> ${esc(r.temporal?.state||"unknown")}</p><p class="meta">Typed by ${esc(r.mapping?.id||"Evidence validator")} · version ${esc(r.mapping?.version||r.schemaVersion||"not recorded")} · ${esc(r.mapping?.method||"not recorded")}<br>Support: ${locators.length?locators.map(locatorText).join(" | "):"Artifact-level support retained; see ordinary Fact"}</p><h4>UBO/KYC CONCLUSION — NOT PERFORMED</h4></section>`;}
function fact(f){return`<div class="fact ${esc(f.requestStatus)}"><b>${esc(f.semanticConceptId||f.schemaFieldId||"Fact")}</b> = <b>${esc(typeof f.factValue==="object"?JSON.stringify(f.factValue):f.factValue)}</b><p class="meta">${esc(f.requestStatus||"")} · ${esc(f.groundingType||"")} · support ${esc(f.supportState||"unknown")}${(f.supportingArtifactIds||[]).length?`<br>Supporting Artifacts: ${f.supportingArtifactIds.map(esc).join(", ")}`:""}</p>${f.rawRepresentation?`<div class="meta">${esc(f.rawRepresentation)}</div>`:""}</div>${relationshipCard(f.typedRelationship,f.supportLocators||[])}`;}
