function historyRun(r){const failed=r.status==="failed",lineage=`<details><summary>Support and Artifact lineage</summary><pre>${esc(JSON.stringify({support:r.supportAssessment,lineage:r.lineage},null,2))}</pre></details>`;if(failed)return`<details class="artifact historical-failure"><summary><b>Earlier failed interpretation attempt</b> · ${esc(fmt(r.completedAt||r.startedAt))}</summary><p class="meta">Retained for audit history. This is not the current interpretation and no facts were persisted.</p><div class="status-grid"><span>Provider: <b>${esc(r.provider||"not recorded")}</b></span><span>Model: <b>${esc(r.modelIdentifier||"not recorded")}</b></span><span>Execution: <b>${esc(r.executionMode)}</b></span><span>Historical status: <b>failed</b></span></div>${r.errorMessage?`<p class="historical-message">${esc(r.errorMessage)}</p>`:""}${lineage}</details>`;return`<div class="artifact"><h3>${esc(fmt(r.completedAt||r.startedAt))}</h3><div class="status-grid"><span>Provider: <b>${esc(r.provider||"not recorded")}</b></span><span>Model: <b>${esc(r.modelIdentifier||"not recorded")}</b></span><span>Execution: <b>${esc(r.executionMode)}</b></span><span>Status: <b>${esc(r.status)}</b></span></div><p class="meta">Facts ${r.summary.factCount} · requested ${r.summary.requested} · discovered ${r.summary.discovered} · derived ${r.summary.derived}</p>${providerEvaluation(r)}${r.facts.map(fact).join("")}${lineage}</div>`;}
