const human=v=>String(v||"").replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase()),shortValue=v=>{const s=typeof v==="object"?JSON.stringify(v):String(v??"");return s.length>220?`${s.slice(0,217)}...`:s;};
