function a4aPreview(){const need=selectedNeed(),facts=selectedFacts(),requested=$("a4aMethod").value,comparison=$("a4aComparison").value;if(!need||!facts.length)return{method:null,semantic:false,text:"Select one Information Need and at least one Fact. Selection makes no AI call."};if(requested!=="automatic")return{method:requested,semantic:requested==="semantic",text:`Advanced override: ${human(requested)}.`};const same=facts.map(f=>f.semanticConceptId===need.schemaFieldId);if(same.every(v=>!v))return{method:"normalized_text",semantic:false,text:"Automatic route: deterministic concept mismatch; no AI call expected."};if(!comparison)return{method:"semantic",semantic:true,text:"Automatic route: no comparison target is persisted or supplied, so semantic relationship evaluation is needed."};if(same.every(Boolean)&&facts.every(f=>typeof f.factValue==="string"&&f.factValue===comparison))return{method:"exact_typed",semantic:false,text:"Automatic route: exact typed equality; no AI call expected."};if(facts.every(f=>typeof f.factValue==="string"))return{method:"normalized_text",semantic:false,text:"Automatic route: conservative normalized comparison; no AI call expected."};return{method:"semantic",semantic:true,text:"Automatic route: deterministic comparison cannot safely resolve this relationship."};}
