let r1Contexts=[],r1OperationKey=crypto.randomUUID();
function updateR1(){const c=r1Contexts.find(x=>x.id===$("r1Context").value),f=$("r1File").files[0];$("r1Ingest").disabled=!(c&&f);$("r1ContextMeta").classList.toggle("hidden",!c);if(c)$("r1ContextMeta").innerHTML=`<b>${esc(c.subjectDisplayName||"Evidence subject")}</b><br>${esc(c.subjectIdentifier||"")} · ${esc(c.contextType||"Evidence context")}<details><summary>Technical context details</summary><pre>${esc(JSON.stringify({contextId:c.id,subjectReferenceId:c.subjectReferenceId,externalReference:c.externalReference},null,2))}</pre></details>`;}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]||"");reader.onerror=()=>reject(new Error("The selected file could not be read"));reader.readAsDataURL(file);});}
