$("r1Context").onchange=updateR1;$("r1File").onchange=()=>{r1OperationKey=crypto.randomUUID();updateR1();};$("r1NewEvent").onclick=()=>{r1OperationKey=crypto.randomUUID();show("r1Message","A new upload-event key is ready. Identical bytes will be a new immutable evidentiary event.");};
$("r1Ingest").onclick=()=>guard.run("r1-ingest",{onStart:()=>{$("r1Ingest").disabled=true;hide("r1Error");activity("r1Activity","Preserving and verifying private Artifact…",true);},work:async()=>{const f=$("r1File").files[0];return request("/api/evidence/r1-ingest",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({idempotencyKey:r1OperationKey,contextId:$("r1Context").value,contentBase64:await fileBase64(f),declaredMediaType:f.type,originalFilename:f.name,sourceChannel:$("r1Channel").value,sourceEffectiveDate:$("r1EffectiveDate").value||null})});},onSuccess:d=>{$("r1Result").insertAdjacentHTML("afterbegin",r1Card(d.result));show("r1Message",d.result.idempotentReplay?"Idempotent retry returned the original Evidence identities; no duplicate was created.":"Private Artifact preserved as a new immutable evidentiary event.");document.querySelector(".r1Reopen").onclick=reopenR1;},onFailure:e=>show("r1Error",e.message),onFinish:()=>{activity("r1Activity","",false);updateR1();}});
