  select.innerHTML=`<option value="">Choose an authorized Evidence context</option>${available.map(c=>`<option value="${esc(c.id)}">${esc(c.subjectDisplayName||c.subjectIdentifier)} — ${esc(c.contextType)}</option>`).join("")}`;
  const preferred=available.find(c=>c.id===previous)||available[0];if(preferred)select.value=preferred.id;$("r2LoadOptions").disabled=!select.value;updateR2Controls();
