function selectedR2Artifacts(){return [...document.querySelectorAll("#r2Artifacts input:checked")].map(x=>x.value);}
function updateR2Controls(){
  const asset=selectedR2Asset(),ids=selectedR2Artifacts(),concepts=r2ConceptList(),media=(asset?.artifacts||[]).filter(a=>ids.includes(a.id)).map(a=>String(a.mediaType||"").split(";")[0].toLowerCase()),supported=media.every(t=>["application/json","text/html","application/pdf","image/png","image/jpeg"].includes(t)||t.endsWith("+json")),ready=!!$("r2Context").value&&!!asset&&ids.length>0&&concepts.length>0;
  $("r2Run").disabled=!ready||!supported;$("r2History").disabled=!ready;$("r2SelectAll").disabled=!asset;$("r2Preflight").disabled=!ready||!supported;const route=media.some(t=>t==="application/pdf"||t.startsWith("image/"))?"multimodal PDF/image":"JSON/HTML text";$("r2Preview").innerHTML=ready?!supported?`<b>Interpretation path: UNSUPPORTED MEDIA</b><br>Provider call expected: <b>NO</b>`:`<b>Interpretation path: ${route} semantic extraction</b><br>Provider call expected for a new operation: <b>YES</b><br>External source recollection: <b>NO</b> · A4a evaluation: <b>NO</b>${r2Preflight?`<br>Media readiness: <b>checked</b>`:"<br>Use Check media readiness for a no-AI validation of preserved bytes and limits."}`:`Choose a context, one Evidence Asset, at least one Artifact and one concept. Selection makes no AI call.`;
}
function resetR2Preflight(){r2Preflight=null;hide("r2PreflightResult");}
function renderR2Artifacts(){const asset=selectedR2Asset();resetR2Preflight();if(!asset){$("r2Artifacts").innerHTML=`<span class="meta">Choose an Evidence Asset to see its preserved Artifacts.</span>`;updateR2Controls();return;}$("r2Artifacts").innerHTML=`<b>${esc(asset.title||asset.evidenceType)}</b><p class="meta">${esc(asset.source?.provider||asset.source?.type||"Evidence source")} · ${esc(asset.accessClass)} · one coherent Evidence Asset</p>${asset.artifacts.map((a,index)=>`<label class="check"><input type="checkbox" value="${esc(a.id)}" ${index===0?"checked":""}><span><b>${esc(a.representationType)}</b> · ${esc(a.mediaType)} · ${esc(a.sizeBytes)} bytes<br><span class="meta">Captured ${esc(fmt(a.capturedAt))}${a.order!=null?` · authoritative order ${esc(a.order)}`:""}</span></span></label>`).join("")}<details><summary>Technical Artifact identities and SHA-256</summary><pre>${esc(JSON.stringify(asset.artifacts.map(a=>({artifactId:a.id,fingerprintValue:a.fingerprintValue})),null,2))}</pre></details>`;document.querySelectorAll("#r2Artifacts input").forEach(x=>x.onchange=()=>{resetR2Preflight();updateR2Controls();});updateR2Controls();}
function loadR2Options(){const contextId=$("r2Context").value;if(!contextId)return;return guard.run("r2-options",{onStart:()=>{$("r2LoadOptions").disabled=true;hide("r2Error");activity("r2Activity","Loading authorized preserved Evidence…",true);},work:()=>request("/api/evidence/r2-options",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId})}),onSuccess:d=>{r2Options=d.result;$("r2Asset").disabled=!r2Options.assets.length;$("r2Asset").innerHTML=`<option value="">Choose one Evidence Asset</option>${r2Options.assets.map(a=>`<option value="${esc(a.id)}">${esc(a.title||a.evidenceType)} — captured ${esc(fmt(a.observedAt))} — ${esc(a.accessClass)} — ${a.artifacts.length} Artifact${a.artifacts.length===1?"":"s"}</option>`).join("")}`;$("r2Artifacts").innerHTML=r2Options.assets.length?`<span class="meta">Choose an Evidence Asset. No source or provider call was made.</span>`:`<span class="meta">No authorized preserved Artifacts were found in this context.</span>`;show("r2Message",`Authorized Evidence loaded (${r2Options.assets.length} Asset${r2Options.assets.length===1?"":"s"}). External source call: NO. AI call: NO.`);updateR2Controls();},onFailure:e=>show("r2Error",e.message),onFinish:()=>{$("r2LoadOptions").disabled=!$("r2Context").value;activity("r2Activity","",false);}});}
function r2Body(){const correlation=$("r2Correlation").value.trim();return{contextId:$("r2Context").value,operationKey:$("r2OperationKey").value,artifactIds:selectedR2Artifacts(),requestedConcepts:r2ConceptList(),extractionContext:{...($("r2Jurisdiction").value.trim()?{jurisdiction:$("r2Jurisdiction").value.trim()}:{}),...($("r2Language").value.trim()?{language:$("r2Language").value.trim()}:{}),...($("r2Purpose").value.trim()?{purpose:$("r2Purpose").value.trim()}:{})},correlation:correlation?{requestId:correlation}:{}};}
function locatorText(l){if(l.kind==="pdf"||l.locatorKind==="pdf")return`PDF page ${esc(l.pageStart||l.page_start)}${(l.pageEnd||l.page_end)!==(l.pageStart||l.page_start)?`–${esc(l.pageEnd||l.page_end)}`:""}: ${esc(l.excerpt||l.supportExcerpt||l.description||l.supportDescription)}`;if(l.kind==="image"||l.locatorKind==="image")return`Image support: ${esc(l.description||l.supportDescription||l.excerpt||l.supportExcerpt)}`;return`${esc(l.jsonPath||l.domReference||l.json_path||l.dom_reference||"Source excerpt")}: ${esc(l.excerpt||l.supportExcerpt||l.description||l.supportDescription)}`;}
function r2Fact(f){return`<div class="fact ${f.requestRelation==="requested_concept_response"?"requested":"discovered"}"><b>${esc(human(f.semanticConceptId))}</b> = <b>${esc(shortValue(f.value))}</b><p class="meta">${f.requestRelation==="requested_concept_response"?"Responsive to requested neutral concept":"Open discovery"} · persisted A3 status ${esc(f.persistedRequestStatus)} · ${esc(f.groundingType)} · support ${esc(f.supportState)}<br>Supporting Artifacts: ${(f.supportingArtifactIds||[]).map(esc).join(", ")}</p>${(f.supportLocators||[]).length?`<details><summary>Source locations (${f.supportLocators.length})</summary>${f.supportLocators.map(l=>`<p class="meta">${locatorText(l)}</p>`).join("")}</details>`:`<p class="error">No valid source locator was persisted; this Fact requires verification.</p>`}</div>${relationshipCard(f.typedRelationship,f.supportLocators||[])}`;}
function r2Card(result,{historical=false}={}){const op=result.operation||{},failed=op.status==="failed",facts=[...(result.responsiveFacts||[]),...(result.discoveredFacts||[])];return`<section class="artifact history"><span class="badge ${failed?"fixture":"live"}">${historical?"HISTORICAL ":""}${esc(String(op.status||"unknown").toUpperCase())}</span><h3>Targeted interpretation · ${esc(fmt(op.completedAt||op.startedAt))}</h3><div class="status-grid"><span>Outcome: <b>${esc(op.outcome||op.status)}</b></span><span>Provider: <b>${esc(result.extractionRun?.provider||"not called")}</b></span><span>Model: <b>${esc(result.extractionRun?.model||"none")}</b></span><span>Instruction: <b>${esc(result.extractionRun?.instructionReference||"none")}</b></span><span>Typed R4 relationships: <b>${esc(result.typedRelationshipCount||0)}</b></span><span>A4a: <b>not performed</b></span></div>${result.failure?`<p class="error"><b>${esc(result.failure.code)}</b> — ${esc(result.failure.message)}</p>`:""}${(result.requestedConceptOutcomes||[]).length?`<div class="notice"><b>Requested concept outcomes</b><br>${result.requestedConceptOutcomes.map(x=>`${esc(human(x.concept))}: <b>${esc(x.status)}</b>`).join("<br>")}</div>`:""}${facts.length?`<h4>Responsive and discovered A3 Facts</h4>${facts.map(r2Fact).join("")}`:`<p class="meta">No Fact was fabricated for this outcome.</p>`}<p class="meta">Completeness: input ${esc(result.completeness?.input?.state||"not recorded")} · extraction ${esc(result.completeness?.extraction?.state||"not recorded")}<br>Correlation: ${esc(result.correlation?.requestId||"not supplied")}</p><details><summary>Reconstructable Evidence lineage and IDs</summary><pre>${esc(JSON.stringify({operation:op,extractionRun:result.extractionRun,evidence:result.evidence,limitations:result.limitations},null,2))}</pre></details><h4>DOWNSTREAM KYC SATISFACTION — NOT PERFORMED</h4></section>`;}
$("r2Context").onchange=()=>{$("r2LoadOptions").disabled=!$("r2Context").value;r2Options={assets:[]};$("r2Asset").disabled=true;$("r2Asset").innerHTML=`<option value="">Load authorized Evidence</option>`;renderR2Artifacts();};$("r2Asset").onchange=renderR2Artifacts;$("r2Concepts").oninput=updateR2Controls;$("r2LoadOptions").onclick=loadR2Options;$("r2SelectAll").onclick=()=>{document.querySelectorAll("#r2Artifacts input").forEach(x=>{x.checked=true;});updateR2Controls();};
$("r2Preflight").onclick=()=>guard.run("r2-preflight",{onStart:()=>{$("r2Preflight").disabled=true;hide("r2Error");activity("r2Activity","Checking preserved media, integrity and interpretation limits…",true);},work:()=>request("/api/evidence/r2-preflight",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:$("r2Context").value,artifactIds:selectedR2Artifacts()})}),onSuccess:d=>{r2Preflight=d.result;$("r2PreflightResult").innerHTML=`<b>Media readiness passed. AI call: NO.</b><br>${(r2Preflight.artifacts||[]).map(a=>`${esc(a.kind.toUpperCase())} · ${esc(a.mediaType)} · ${esc(a.sizeBytes)} bytes${a.pageCount?` · ${esc(a.pageCount)} page(s)`:""}${a.width?` · ${esc(a.width)}×${esc(a.height)} pixels`:""} · SHA-256 verified`).join("<br>")}<br>Aggregate binary input: ${esc(r2Preflight.aggregateBinaryBytes)} bytes · provider/model capability: <b>${r2Preflight.providerConfigured?"configured":"not configured"}</b>`;$("r2PreflightResult").classList.remove("hidden");updateR2Controls();},onFailure:e=>{r2Preflight=null;show("r2Error",e.message);},onFinish:()=>{activity("r2Activity","",false);updateR2Controls();}});
$("r2NewKey").onclick=()=>{$("r2OperationKey").value=crypto.randomUUID();show("r2Message","A deliberate new interpretation key is ready. Running it will create new immutable A3 history and may make one paid AI request.");updateR2Controls();};
$("r2Run").onclick=()=>guard.run("r2-fresh",{onStart:()=>{$("r2Run").disabled=true;hide("r2Error");activity("r2Activity","Running targeted interpretation of preserved Evidence…",true);},work:()=>request("/api/evidence/r2-interpret",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r2Body())}),onSuccess:d=>{$("r2Results").insertAdjacentHTML("afterbegin",r2Card(d.result));show("r2Message",d.result.replayed?"Existing operation returned. Provider call: NO. New Extraction Run: NO.":d.result.operation.status==="failed"?"The failed operation was preserved truthfully. No conclusion was fabricated.":"New immutable targeted interpretation persisted. Source Evidence was not recollected and A4a was not run.");},onFailure:e=>show("r2Error",e.message),onFinish:()=>{activity("r2Activity","",false);updateR2Controls();}});
$("r2History").onclick=()=>guard.run("r2-history",{onStart:()=>{$("r2History").disabled=true;hide("r2Error");activity("r2Activity","Loading previous targeted interpretations…",true);},work:()=>request("/api/evidence/r2-history",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:$("r2Context").value,artifactIds:selectedR2Artifacts()})}),onSuccess:d=>{const operations=d.result.operations||[];$("r2Results").insertAdjacentHTML("afterbegin",`<section class="history"><h3>Previous R2 operations</h3>${operations.length?operations.map(op=>r2Card(op.status==="completed"?op.result:{operation:{id:op.id,key:op.operationKey,status:op.status,startedAt:op.startedAt,completedAt:op.completedAt},failure:op.failure,correlation:op.correlation},{historical:true})).join(""):`<p class="meta">No previous targeted interpretations for this selection.</p>`}</section>`);show("r2Message",`History loaded (${operations.length} operation${operations.length===1?"":"s"}). AI call: NO. New Extraction Run: NO.`);},onFailure:e=>show("r2Error",e.message),onFinish:()=>{activity("r2Activity","",false);updateR2Controls();}});
$("r2OperationKey").value=crypto.randomUUID();fetch("/api/evidence/r2-config").then(r=>r.json()).then(c=>{$("r2Config").innerHTML=`<span>Database: <b>${c.database?"ready":"not configured"}</b></span><span>Artifact storage: <b>${c.artifactStorage?"ready":"not configured"}</b></span><span>Semantic provider: <b>${c.semanticProviderConfigured?"ready":"not configured"}</b></span><span>JSON/HTML: <b>supported</b></span><span>PDF/PNG/JPEG: <b>supported within R3 limits</b></span>`;}).catch(()=>{});
