let a5aContexts=[],a5aLastReconstruction=null,a5bPackages=[];
function a5aLocalNow(){const now=new Date(Date.now()-1000),offset=now.getTimezoneOffset()*60000;return new Date(now-offset).toISOString().slice(0,16);}
function updateA5aControls(){const context=a5aContexts.find((item)=>item.id===$("a5aContext").value),ready=!!context&&!!$("a5aAsOf").value;$("runA5a").disabled=!ready;$("a5aContextMeta").classList.toggle("hidden",!context);if(context)$("a5aContextMeta").innerHTML=`<b>${esc(context.subjectDisplayName||"Evidence subject")}</b><br>${esc(context.subjectIdentifier||"")} · ${esc(context.contextType||"Evidence context")}<br><span class="meta">Current tenant/context authorization will be applied. Internal identities are secondary.</span><details><summary>Technical context identity</summary><pre>${esc(JSON.stringify({contextId:context.id,subjectReferenceId:context.subjectReferenceId,externalReference:context.externalReference},null,2))}</pre></details>`;updateA5bControls();}
function a5aEntryCard(item){return`<div class="artifact"><b>${esc(fmt(item.availableAt))} · ${esc(human(item.category))}</b><br>${esc(item.summary)}${item.status?` <b class="${item.status==="failed"?"failed":""}">${esc(item.status)}</b>`:""}<p class="meta">Known/available ${esc(fmt(item.availableAt))}${item.occurredAt!==item.availableAt?` · occurred/source time ${esc(fmt(item.occurredAt))}`:""}<br>${esc(item.sourceRecordType)}</p>${(item.limitations||[]).map(x=>`<p class="meta">Limitation: ${esc(x)}</p>`).join("")}<details><summary>Safe Evidence reference and details</summary><pre>${esc(JSON.stringify({reference:item.evidenceReference,contextId:item.contextId,subjectReferenceId:item.subjectReferenceId,details:item.details},null,2))}</pre></details></div>`;}
function a5aGroup(entries,title,categories,open=false){const items=entries.filter((item)=>categories.includes(item.category));return`<details class="artifact" ${open?"open":""}><summary><b>${esc(title)} (${items.length})</b></summary>${items.length?items.map(a5aEntryCard).join(""):`<p class="meta">No ${esc(title.toLowerCase())} were reconstructably available by this time.</p>`}</details>`;}
function renderA5a(data){a5aLastReconstruction=data;const entries=data.entries||[],counts=data.summary?.byCategory||{};$("a5aResult").innerHTML=`<section class="history"><span class="badge live">EVIDENCE RECONSTRUCTION</span><h2>As known by ${esc(fmt(data.asOf))}</h2><h3>${esc(data.subject.displayName||data.context.subjectDisplayName||"Evidence subject")}</h3><p class="meta">${esc(data.context.subjectIdentifier||"")} · availability rules ${esc(data.availabilityRulesVersion)} · transient read model</p><div class="status-grid">${Object.entries(counts).map(([key,value])=>`<span>${esc(human(key))}: <b>${esc(value)}</b></span>`).join("")}<span>Total entries: <b>${esc(entries.length)}</b></span></div>${a5aGroup(entries,"Chronological timeline",["requirement","information_need","collection","acquisition","asset","artifact","extraction","interpretation","fact","support","relationship","lineage","verification","evaluation","assessment"],true)}${a5aGroup(entries,"Collections, acquisitions and failures",["collection","acquisition"])}${a5aGroup(entries,"Preserved Assets and Artifacts",["asset","artifact"])}${a5aGroup(entries,"Extraction, Facts, support and relationships",["extraction","interpretation","fact","support","relationship","lineage","verification"])}${a5aGroup(entries,"A4a evaluations",["evaluation"])}${a5aGroup(entries,"A4b coverage assessments",["assessment"])}<h3>Known reconstruction limitations</h3><div class="notice">${data.limitations.map((item)=>`• ${esc(item)}`).join("<br>")}</div><h3>DOWNSTREAM KYC/UBO DECISION</h3><p class="error"><b>NOT RECONSTRUCTED UNLESS SEPARATELY INTEGRATED</b></p><details><summary>Projection scope and side-effect proof</summary><pre>${esc(JSON.stringify({authorizedUsing:data.authorizedUsing,sideEffects:data.sideEffects,downstreamDecision:data.downstreamDecision},null,2))}</pre></details></section>`;show("a5aMessage",`Reconstruction complete (${entries.length} entries). Source call: NO. AI call: NO. Evidence write: NO.`);updateA5bControls();}
async function loadA5aOptions(){try{const [config,options]=await Promise.all([request("/api/evidence/a5a-config"),request("/api/evidence/a5a-options")]);a5aContexts=options.result.contexts||[];$("a5aConfig").innerHTML=`<span>Database: <b>${config.database?"ready":"not configured"}</b></span><span>Rules: <b>${esc(config.availabilityRulesVersion)}</b></span><span>Source/AI calls: <b>none</b></span><span>Writes: <b>none</b></span>`;$("a5aContext").disabled=!a5aContexts.length;$("a5aContext").innerHTML=`<option value="">Choose an authorized subject/context</option>${a5aContexts.map((context)=>`<option value="${esc(context.id)}">${esc(context.subjectDisplayName||context.subjectIdentifier)} — ${esc(context.contextType)}</option>`).join("")}`;updateA5aControls();}catch(error){show("a5aError",error.message);}}
function resetA5aFreezeInput(){a5aLastReconstruction=null;updateA5aControls();}
$("a5aAsOf").value=a5aLocalNow();$("a5aContext").onchange=resetA5aFreezeInput;$("a5aAsOf").onchange=resetA5aFreezeInput;
$("runA5a").onclick=()=>guard.run("a5a-reconstruct",{onStart:()=>{$("runA5a").disabled=true;hide("a5aError");activity("a5aActivity","Reconstructing the Evidence picture at the selected time…",true);},work:()=>{const context=a5aContexts.find((item)=>item.id===$("a5aContext").value);return request("/api/evidence/a5a-reconstruct",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:context.id,subjectReferenceId:context.subjectReferenceId,asOf:new Date($("a5aAsOf").value).toISOString()})});},onSuccess:(data)=>renderA5a(data.result),onFailure:(error)=>show("a5aError",error.message),onFinish:()=>{activity("a5aActivity","",false);updateA5aControls();}});
loadA5aOptions();

function currentA5aContext(){return a5aContexts.find((item)=>item.id===$("a5aContext").value)||null;}
function updateA5bControls(){const context=currentA5aContext(),other=$("a5bPurpose").value==="other";$("a5bPurposeLabel").disabled=!other;$("listA5b").disabled=!context;$("freezeA5b").disabled=!a5aLastReconstruction||!context||a5aLastReconstruction.context.id!==context.id||!$("a5bOperationKey").value||(other&&!$("a5bPurposeLabel").value.trim());}
function a5bPurpose(){return{code:$("a5bPurpose").value,label:$("a5bPurpose").value==="other"?$("a5bPurposeLabel").value.trim():null};}
function a5bPackageCard(result,{listed=false}={}){const p=result.package||result,manifest=result.manifest,integrity=result.integrity;return`<section class="artifact history" data-package-id="${esc(p.id)}"><span class="badge live">IMMUTABLE PACKAGE${result.replayed?" · IDEMPOTENT REPLAY":""}</span><h3>${esc(p.purposeCode.replaceAll("_"," "))} · ${esc(fmt(p.frozenAt))}</h3><div class="status-grid"><span>Package ID: <b>${esc(p.id)}</b></span><span>As known by: <b>${esc(fmt(p.asOf))}</b></span><span>Entries: <b>${esc(manifest?.entries?.length??"reopen to inspect")}</b></span><span>Manifest: <b>${esc(p.manifestVersion)}</b></span></div><p class="meta">Manifest SHA-256: ${esc(p.manifestFingerprintValue)}${p.derivedFromPackageId?`<br>Derived from Package: ${esc(p.derivedFromPackageId)}`:""}</p>${integrity?`<div class="notice"><b>PACKAGE MANIFEST VERIFIED</b><br>${esc(integrity.meaning)}<br><b>This does not verify Evidence truth and does not approve KYC or UBO.</b></div>`:""}<p><button class="a5bReopen" data-package-id="${esc(p.id)}">Reopen frozen Package</button> <button class="a5bVerify" data-package-id="${esc(p.id)}">Verify Package manifest</button></p>${manifest?`${a5aGroup(manifest.entries,"Frozen chronology",["requirement","information_need","collection","acquisition","asset","artifact","extraction","interpretation","fact","support","relationship","lineage","verification","evaluation","assessment"],!listed)}<h4>Frozen A5a limitations</h4><div class="notice">${(manifest.limitations||[]).map(x=>`• ${esc(x)}`).join("<br>")}</div><h4>DOWNSTREAM KYC/UBO DECISION — NOT PERFORMED</h4>`:""}<details><summary>Technical Package details</summary><pre>${esc(JSON.stringify({package:p,integrity:integrity||null},null,2))}</pre></details></section>`;}
function populateA5bPackages(packages){a5bPackages=packages;$("a5bDerivedFrom").innerHTML=`<option value="">No predecessor</option>${packages.map(p=>`<option value="${esc(p.id)}">${esc(fmt(p.frozenAt))} · ${esc(p.purposeCode.replaceAll("_"," "))} · ${esc(p.id.slice(0,8))}</option>`).join("")}`;$("a5bResults").insertAdjacentHTML("afterbegin",`<section class="history"><h3>Existing immutable Packages (${packages.length})</h3>${packages.length?packages.map(p=>a5bPackageCard(p,{listed:true})).join(""):`<p class="meta">No Package has been frozen for this subject/context.</p>`}</section>`);}
function loadA5bPackages(){const context=currentA5aContext();if(!context)return Promise.resolve();return guard.run("a5b-list",{onStart:()=>{$("listA5b").disabled=true;hide("a5bError");activity("a5bActivity","Loading authorized immutable Packages…",true);},work:()=>request("/api/evidence/a5b-list",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:context.id,subjectReferenceId:context.subjectReferenceId})}),onSuccess:data=>{populateA5bPackages(data.result.packages||[]);show("a5bMessage",`Loaded ${data.result.packages.length} Package(s). Source call: NO. AI call: NO.`);},onFailure:error=>show("a5bError",error.message),onFinish:()=>{activity("a5bActivity","",false);updateA5bControls();}});}
$("a5bPurpose").onchange=updateA5bControls;$("a5bPurposeLabel").oninput=updateA5bControls;$("a5bNewKey").onclick=()=>{$("a5bOperationKey").value=crypto.randomUUID();show("a5bMessage","A deliberate new freeze key is ready. A new Package will be created if you freeze.");updateA5bControls();};$("listA5b").onclick=loadA5bPackages;
$("freezeA5b").onclick=()=>guard.run("a5b-freeze",{onStart:()=>{$("freezeA5b").disabled=true;hide("a5bError");activity("a5bActivity","Freezing the complete authorized A5a reconstruction…",true);},work:()=>{const context=currentA5aContext();return request("/api/evidence/a5b-freeze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:context.id,subjectReferenceId:context.subjectReferenceId,asOf:a5aLastReconstruction.asOf,purpose:a5bPurpose(),operationKey:$("a5bOperationKey").value,derivedFromPackageId:$("a5bDerivedFrom").value||null})});},onSuccess:data=>{$("a5bResults").insertAdjacentHTML("afterbegin",a5bPackageCard(data.result));show("a5bMessage",data.result.replayed?"Existing Package returned for the same operation key and request.":"Immutable Package frozen. No source or AI call was made.");loadA5bPackages();},onFailure:error=>show("a5bError",error.message),onFinish:()=>{activity("a5bActivity","",false);updateA5bControls();}});
$("a5bResults").onclick=event=>{const button=event.target.closest("button[data-package-id]");if(!button)return;const context=currentA5aContext(),route=button.classList.contains("a5bVerify")?"verify":"reopen",routePath=route==="verify"?"/api/evidence/a5b-verify":"/api/evidence/a5b-reopen";guard.run(`a5b-${route}-${button.dataset.packageId}`,{onStart:()=>{button.disabled=true;hide("a5bError");activity("a5bActivity",route==="verify"?"Verifying stored Package manifest…":"Reopening frozen Package under current authorization…",true);},work:()=>request(routePath,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({contextId:context.id,packageId:button.dataset.packageId})}),onSuccess:data=>{$("a5bResults").insertAdjacentHTML("afterbegin",a5bPackageCard(data.result));show("a5bMessage",route==="verify"?"PACKAGE MANIFEST VERIFIED. Package integrity only; Evidence truth and KYC/UBO were not verified.":"Frozen Package reopened. A5a was not rerun and no source or AI call was made.");},onFailure:error=>show("a5bError",error.message),onFinish:()=>{button.disabled=false;activity("a5bActivity","",false);updateA5bControls();}});};
$("a5bOperationKey").value=crypto.randomUUID();fetch("/api/evidence/a5b-config").then(r=>r.json()).then(c=>{$("a5bConfig").innerHTML=`<span>Database: <b>${c.database?"ready":"not configured"}</b></span><span>Manifest: <b>${esc(c.manifestVersion)}</b></span><span>Canonicalization: <b>${esc(c.canonicalizationVersion)}</b></span><span>Source/AI calls: <b>none</b></span>`;}).catch(()=>{});updateA5bControls();
